// Parse MO data
const data = $input.first().json;

return [{
  json: {
    mo_number: data.mo_number || 'N/A',
    product: data.product_name || 'Unknown',
    qty: data.qty || 0,
    customer: data.customer_name || 'Internal',
    start_time: new Date().toISOString(),
    expected_duration_hours: data.expected_hours || 8
  }
}];

